import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"معايير الملاحظة أولاً ثم التدخل المحدود","description":"","frontmatter":{},"headers":[],"relativePath":"ar/83-先观测后有限干涉准则.md","filePath":"ar/83-先观测后有限干涉准则.md","lastUpdated":1789183869000}'),h={name:"ar/83-先观测后有限干涉准则.md"};function l(o,t,i,n,_,p){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="معايير-الملاحظة-أولاً-ثم-التدخل-المحدود" tabindex="-1">معايير الملاحظة أولاً ثم التدخل المحدود <a class="header-anchor" href="#معايير-الملاحظة-أولاً-ثم-التدخل-المحدود" aria-label="Permalink to &quot;معايير الملاحظة أولاً ثم التدخل المحدود&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>83</td></tr><tr><td>الوحدة</td><td>التفاعل عبر الأبعاد وقواعد الزمن</td></tr><tr><td>الكلمات المفتاحية</td><td>الملاحظة أولاً، التدخل المحدود، بروتوكول الملاحظة، عتبة التدخل، تقييم السببية</td></tr></tbody></table><h2 id="أولاً-المفهوم-الجوهري-للمعايير" tabindex="-1">أولاً: المفهوم الجوهري للمعايير <a class="header-anchor" href="#أولاً-المفهوم-الجوهري-للمعايير" aria-label="Permalink to &quot;أولاً: المفهوم الجوهري للمعايير&quot;">​</a></h2><p>«الملاحظة أولاً ثم التدخل المحدود» هو المعيار الأول لعمليات الارتداد الزمني وعلم الآثار عبر الأبعاد في كون هنغ يوان، ويمكن إجمال مفهومه الجوهري في ست عشرة كلمة: «راقب دون لمس، وقِس دون إزعاج، وفكّر قبل التحرك، وحرّك بقدر.» قيام هذا المعيار على إجلال عميق للقوانين السببية للكون — فأي تدخل مباشر في الماضي أو في بُعد آخر قد يطلق تفاعلات متسلسلة سببية غير متوقعة، والملاحظة المسبقة الكافية هي الوسيلة الموثوقة الوحيدة لتقليل المخاطر إلى أدنى حد.</p><p>الأساس الفلسفي للمعيار هو مبدأ «التواضع المعرفي». يعترف كون هنغ يوان بأنه حتى قوى الأبعاد العليا لا تستطيع الإحاطة الكاملة بجميع الصلات السببية لعقدة زمنية أو حضارة بُعد. لذلك، قبل اتخاذ أي إجراء تدخل، يجب إجراء ملاحظة شاملة بأقصى درجات الحذر، وفهم البنية السببية واتجاهات التطور للهدف المطلوب بأكبر قدر ممكن من الاكتمال. وفقط بشرط كفاية بيانات الملاحظة ووضوح تقييم المخاطر، يُسمح بتدخل محدود.</p><p>«الملاحظة أولاً ثم التدخل المحدود» ليس خطوتين مستقلتين، بل حلقة تشغيلية عضوية مغلقة: فالملاحظة تمد التدخل بالأساس، ونتائج التدخل تتغذى راجعةً بوصفها بيانات ملاحظة جديدة، وهما يتعاقبان دورياً ويتقدمان تدريجياً. تضمن هذه الحلقة المغلقة أن كل تدخل مبني على أحدث أساس معرفي وأكمله.</p><h2 id="ثانياً-المواصفات-التشغيلية-لمرحلة-الملاحظة" tabindex="-1">ثانياً: المواصفات التشغيلية لمرحلة الملاحظة <a class="header-anchor" href="#ثانياً-المواصفات-التشغيلية-لمرحلة-الملاحظة" aria-label="Permalink to &quot;ثانياً: المواصفات التشغيلية لمرحلة الملاحظة&quot;">​</a></h2><p>مرحلة الملاحظة هي أساس العملية التشغيلية بأكملها، وجودتها تحدد مباشرة سلامة التدخل اللاحق وفاعليته. يجب أن تتبع مرحلة الملاحظة المواصفات التشغيلية التالية:</p><h3 id="_2-1-متطلبات-مدة-الملاحظة" tabindex="-1">2.1 متطلبات مدة الملاحظة <a class="header-anchor" href="#_2-1-متطلبات-مدة-الملاحظة" aria-label="Permalink to &quot;2.1 متطلبات مدة الملاحظة&quot;">​</a></h3><p>يجب ألا تقل مدة الملاحظة عن 1٪ من الطول الكلي للفترة المستهدفة، وألا تقل المدة المطلقة عن 72 ساعة من الزمن القياسي للبُعد الخاص. فمثلاً، لملاحظة ارتدادية لفترة تاريخية تمتد 100 عام، يجب ألا تقل مرحلة الملاحظة الخالصة عن عام واحد؛ ولملاحظة فترة تمتد 10 أعوام، يجب ألا تقل مرحلة الملاحظة الخالصة عن 72 ساعة. يضمن هذا الشرط الأدنى للمدة التقاط المراقب للتغيرات الدورية والاتجاهات طويلة المدى في الفترة المستهدفة، وتجنب الأحكام أحادية الجانب الناتجة عن نافذة ملاحظة قصيرة للغاية.</p><h3 id="_2-2-متطلبات-أبعاد-الملاحظة" tabindex="-1">2.2 متطلبات أبعاد الملاحظة <a class="header-anchor" href="#_2-2-متطلبات-أبعاد-الملاحظة" aria-label="Permalink to &quot;2.2 متطلبات أبعاد الملاحظة&quot;">​</a></h3><p>يجب أن تغطي الملاحظة الأبعاد الخمسة التالية، فلا يغيب أي منها:</p><table tabindex="0"><thead><tr><th>بُعد الملاحظة</th><th>المحتوى المحدد</th><th>طريقة الملاحظة</th></tr></thead><tbody><tr><td>البُعد المادي</td><td>البيئة الجغرافية، الأنظمة البيئية، البنى التحتية، توزيع الموارد المادية</td><td>المسح المكاني، التحليل المادي</td></tr><tr><td>البُعد الطاقي</td><td>توزيع كثافة الطاقة، متغيرات القوانين، أنماط تدفق الطاقة</td><td>التحليل الطيفي للطاقة، كشف القوانين</td></tr><tr><td>بُعد الحياة</td><td>توزيع الأنواع، أعداد الجمهرات، الحالة الصحية، مستوى التطور</td><td>مسح العلامات الحيوية، أخذ العينات الجينية</td></tr><tr><td>بُعد الوعي</td><td>الشكل الحضاري، البنية الاجتماعية، الأفكار والمفاهيم، نزعات الوعي الجماعي</td><td>الإصغاء السلبي لمجال الوعي، التحليل الثقافي</td></tr><tr><td>البُعد السببي</td><td>السلاسل السببية الرئيسية، العقد التاريخية، اتجاهات التطور، المخاطر المحتملة</td><td>تتبع السلاسل السببية، استنتاج الاتجاهات</td></tr></tbody></table><h3 id="_2-3-متطلبات-حياد-الملاحظة" tabindex="-1">2.3 متطلبات حياد الملاحظة <a class="header-anchor" href="#_2-3-متطلبات-حياد-الملاحظة" aria-label="Permalink to &quot;2.3 متطلبات حياد الملاحظة&quot;">​</a></h3><p>يجب أن تحافظ مرحلة الملاحظة على الحياد بصرامة؛ فلا يجوز للمراقب التأثير في موضوع الملاحظة بأي شكل. السلوكيات المحظورة تحديداً تشمل: أي شكل من أشكال التواصل مع موضوع الملاحظة، وترك أي أثر مادي أو طاقي في منطقة الملاحظة، وتوجيه سلوك موضوع الملاحظة أو التلميح إليه، وإطلاق أي تموجات فكرية قابلة للإدراك في مجال الوعي.</p><p>يجب أن تكون حالة وجود المراقب في مرحلة الملاحظة «إدراكاً سلبياً خالصاً»، أي تلقي المعلومات فقط دون إخراج أي معلومات. يولّد جهاز تثبيت المرساة للمراقب طبقة من «حقل حجب الملاحظة»، تضمن ألا يدرك موضوع الملاحظة وجود المراقب، كما تمنع المراقب من إطلاق إشارات مزعجة عن غير قصد.</p><h2 id="ثالثاً-تعريف-التدخل-المحدود-وعتبته" tabindex="-1">ثالثاً: تعريف التدخل المحدود وعتبته <a class="header-anchor" href="#ثالثاً-تعريف-التدخل-المحدود-وعتبته" aria-label="Permalink to &quot;ثالثاً: تعريف التدخل المحدود وعتبته&quot;">​</a></h2><p>بعد إكمال مرحلة الملاحظة، يجب على فريق التشغيل تقديم «تقرير الملاحظة وتقييم جدوى التدخل»، ولا يدخل مرحلة التدخل المحدود إلا بعد موافقة لجنة قوانين الزمن أو إدارة الأبعاد. يتجلى «المحدود» في «التدخل المحدود» في المستويات الثلاثة التالية:</p><h3 id="_3-1-محدودية-النطاق" tabindex="-1">3.1 محدودية النطاق <a class="header-anchor" href="#_3-1-محدودية-النطاق" aria-label="Permalink to &quot;3.1 محدودية النطاق&quot;">​</a></h3><p>يجب أن يقتصر سلوك التدخل بصرامة على «المنطقة المرخص للتدخل فيها» المحددة في وثيقة الموافقة، والتي لا تتجاوز عادة 1٪ من المساحة الكلية لمنطقة الملاحظة. يُعد أي سلوك تدخل خارج المنطقة المرخص لها مخالفة، ويتحمل المنفذ المسؤولية القانونية.</p><h3 id="_3-2-محدودية-الدرجة" tabindex="-1">3.2 محدودية الدرجة <a class="header-anchor" href="#_3-2-محدودية-الدرجة" aria-label="Permalink to &quot;3.2 محدودية الدرجة&quot;">​</a></h3><p>يجب ألا يتجاوز إخراج الطاقة وحجم المعلومات المحقونة للتدخل «عتبة التدخل». تحدد عتبة التدخل ديناميكياً وفقاً للحساسية السببية للهدف، بصيغة الحساب: عتبة التدخل = إجمالي طاقة المنطقة المستهدفة × معامل الحساسية السببية × 0.0001. يتراوح معامل الحساسية السببية بين 0.1 و10؛ وكلما ارتفع مستوى الحضارة وكانت العقدة التاريخية أكثر حرجاً، كبر المعامل. وهذا يعني أن عتبة التدخل للعقد التاريخية الحرجة منخفضة للغاية، فلا يُسمح تقريباً بأي حقن طاقي جوهري.</p><h3 id="_3-3-محدودية-الزمن" tabindex="-1">3.3 محدودية الزمن <a class="header-anchor" href="#_3-3-محدودية-الزمن" aria-label="Permalink to &quot;3.3 محدودية الزمن&quot;">​</a></h3><p>يجب ألا تتجاوز مدة سلوك التدخل 10٪ من المدة الكلية لمرحلة الملاحظة، وألا تتجاوز المدة المطلقة 24 ساعة من الزمن القياسي للبُعد الخاص. بعد انتهاء التدخل، يجب على المنفذ الانسحاب فوراً من الفترة المستهدفة أو البُعد المستهدف، دون مكث.</p><h2 id="رابعاً-تقييم-السببية-وتصحيحها-بعد-التدخل" tabindex="-1">رابعاً: تقييم السببية وتصحيحها بعد التدخل <a class="header-anchor" href="#رابعاً-تقييم-السببية-وتصحيحها-بعد-التدخل" aria-label="Permalink to &quot;رابعاً: تقييم السببية وتصحيحها بعد التدخل&quot;">​</a></h2><p>بعد انتهاء التدخل المحدود، يجب على فريق التشغيل إجراء «تقييم السببية بعد التدخل» فوراً، عبر مراقبة تغيرات السلاسل السببية الناجمة عن سلوك التدخل من خلال شبكة المرساة. يشمل محتوى التقييم: سعة الانحراف السببي، ومدى انتشار الانحراف، واتجاه تطور الانحراف طويل المدى، ووجود خطر المفارقات.</p><p>إذا كشف التقييم أن الانحراف السببي تجاوز النطاق المقبول (تجاوزت سعة الانحراف 0.01٪ من إجمالي السببية في المنطقة المستهدفة)، يجب على فريق التشغيل إطلاق «إجراء تصحيح السببية» فوراً. تشمل طرق تصحيح السببية: حقن معلومات تعويضية في العقد الزمنية اللاحقة، والضبط الدقيق للسلاسل السببية عبر شبكة المرساة، وفي الحالات القصوى إجراء ارتداد ثانٍ لمعادلة أثر التدخل السابق.</p><p>يجب تسجيل جميع سلوكيات التدخل ونتائج تقييم السببية الخاصة بها في «أرشيف العمليات الزمنية» لحفظ دائم، لصالح عمليات التدقيق والبحث اللاحقة.</p><h2 id="الخلاصة" tabindex="-1">الخلاصة <a class="header-anchor" href="#الخلاصة" aria-label="Permalink to &quot;الخلاصة&quot;">​</a></h2><p>معايير الملاحظة أولاً ثم التدخل المحدود هي ثمرة حكمة كون هنغ يوان في ميدان العمليات الزمنية وعمليات الأبعاد. بالملاحظة الكافية أساساً، وبالعتبات الصارمة حداً، وبالتقييم اللاحق ضماناً، تبني نموذجاً تشغيلياً قوامه «اعرف ثم تحرك، وتحرك بقدر». الغرض الجوهري من هذه المعايير ليس تقييد أيدي الاستكشاف، بل ضمان ألا يتم أي استكشاف على حساب تدمير النظام السببي للكون.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>82-时间回溯基本原则 (المبادئ الأساسية للارتداد الزمني)</li><li>84-考古协议总纲 (البروتوكول العام لعلم الآثار)</li><li>89-时间悖论防控机制 (آلية الوقاية من مفارقات الزمن وضبطها)</li></ul>',32)])])}const b=a(h,[["render",l]]);export{c as __pageData,b as default};
